"""Cross-over check: OUR JAX learner trained on the streams generated by the OFFICIAL SCR generator
(work/env_data/*, written by scripts/oracle/official_pipeline.py).  Paired with the official learner on the same
streams, this separates "learner" from "stream" when our small-scale numbers and the official pipeline disagree.

    JAX_PLATFORMS=cpu uv run python -m scripts.oracle.ours_on_official_streams [--seeds 0 1 2 3 4]
-> runs/oracle_pipeline/ours_on_official_streams.json
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import time

import jax
import jax.numpy as jnp
import numpy as np

from scripts.oracle.official_pipeline import ENV, PY, WORK
from scripts.oracle.pipeline_summary import ms
from src import algorithm as A
from src.model import ACT_ID, INIT_GAIN, REINIT_GAIN, init_mlp

REPO = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
INIT_BASE = 90_000   # init seed of run s = INIT_BASE + s (our key tree: fold_in(PRNGKey(.), 2))
# name: (stream dir, act, hp kwargs) -- the same arms as the official pipeline cases
CASES = {
    "flip_relu_bp_0.01": ("flip_one_3000000", "relu", dict(lr=0.01)),
    "flip_tanh_bp_0.01": ("flip_one_3000000", "tanh", dict(lr=0.01)),
    "rs_relu_bp_0.01": ("resample_1000000", "relu", dict(lr=0.01)),
    "rs_relu_l2_1e-2": ("resample_1000000", "relu", dict(lr=0.01, wd=1e-2)),
    "rs_relu_snp_1e-3": ("resample_1000000", "relu", dict(lr=0.01, wd=1e-2, sigma=1e-3)),
    "rs_relu_cbp_1e-4_default": ("resample_1000000", "relu", dict(lr=0.01, rho=1e-4, mt=10, eta=0.99)),
}


def stream(sdir, seed):
    npz = f"{WORK}/env_npz/{sdir}_{seed}.npz"
    if not os.path.exists(npz):
        os.makedirs(os.path.dirname(npz), exist_ok=True)
        code = ("import pickle, numpy as np, sys; X, Y, _ = pickle.load(open(sys.argv[1], 'rb')); "
                "np.savez(sys.argv[2], X=X.numpy().astype(np.uint8), Y=Y.numpy()[:, 0])")
        subprocess.run([PY, "-c", code, f"{WORK}/env_data/{sdir}/{seed}", npz], check=True, env=ENV)
    d = np.load(npz)
    return d["X"], d["Y"]


def run_case(case, seeds):
    sdir, act, kw = CASES[case]
    n = int(sdir.split("_")[-1])
    X = np.stack([stream(sdir, s)[0][:n] for s in seeds])
    Y = np.stack([stream(sdir, s)[1][:n] for s in seeds])
    st = A.Static(n_in=20, widths=(5,), n_out=1, replace_mode="bernoulli")
    hp = A.make_hp(act=ACT_ID[act], reinit_gain=REINIT_GAIN[act], **kw)
    T = 10_000

    def one_run(seed, Xs, Ys):
        root = jax.random.PRNGKey(seed)
        p = init_mlp(jax.random.fold_in(root, 2), 20, (5,), 1, INIT_GAIN[act])
        k_algo = jax.random.fold_in(root, 3)

        def period(carry, xy):
            s, g = carry
            xp, yp = xy

            def step(c, xy1):
                s, g = c
                x, y = xy1
                s, info = A.learner_step(st, s, hp, x.astype(jnp.float32)[None], y[None, None],
                                         jax.random.fold_in(k_algo, g))
                return (s, g + 1), info["loss"]

            (s, g), l = jax.lax.scan(step, (s, g), (xp, yp))
            return (s, g), l.mean()

        _, per = jax.lax.scan(period, (A.init_state(st, p), jnp.int32(0)),
                              (Xs.reshape(-1, T, 20), Ys.reshape(-1, T)))
        return per

    t = time.time()
    per = jax.jit(jax.vmap(one_run))(jnp.asarray([INIT_BASE + s for s in seeds]), jnp.asarray(X), jnp.asarray(Y))
    per = np.asarray(per)
    print(f"[INFO] ours_on_official_streams {case} {time.time() - t:.0f}s", flush=True)
    return per


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--seeds", type=int, nargs="*", default=[0, 1, 2, 3, 4])
    ap.add_argument("--cases", nargs="*", default=list(CASES))
    ap.add_argument("--init_base", type=int, default=90_000)
    ap.add_argument("--out", default="ours_on_official_streams.json")
    a = ap.parse_args()
    global INIT_BASE
    INIT_BASE = a.init_base
    out = os.path.join(REPO, "runs", "oracle_pipeline", a.out)
    res = json.load(open(out)) if os.path.exists(out) else {}
    for case in a.cases:
        per = run_case(case, a.seeds)
        m, _ = _metrics(per)
        res[case] = {"seeds": a.seeds, "ours": {k: ms(v) for k, v in m.items()},
                     "ours_per_seed": {k: np.asarray(v).tolist() for k, v in m.items()},
                     "ours_per10k": per.tolist(), "init_base": INIT_BASE}
        print(f"[METRIC] ours_on_official_streams {case} " + " ".join(f"{k}={v[0]:.4f}" for k, v in
                                                                      res[case]["ours"].items()), flush=True)
        json.dump(res, open(out, "w"), indent=1)


def _metrics(pp):
    """src/eval.py definitions on per-10k-period MSE (S, P)."""
    P = pp.shape[1] // 4 * 4
    bins = pp[:, :P].reshape(len(pp), -1, 4).mean(-1)
    n1m = min(bins.shape[1], 25)
    per = {"whole_run": pp.mean(1), "first_bin": bins[:, 0], "last_bin": bins[:, -1],
           "min_bin_first_1M": bins[:, :n1m].min(1), "last_250k": pp[:, -25:].mean(1)}
    per["delta_lop"] = per["last_250k"] - per["min_bin_first_1M"]
    return per, bins.mean(0)


if __name__ == "__main__":
    main()
